import 'bootstrap/dist/css/bootstrap.min.css';
import Button from 'react-bootstrap/Button';
import { Container,Nav, Navbar, NavDropdown } from "react-bootstrap";
import Logo from "../../Images/Components/Navbar/four.png";
import Offcanvas from 'react-bootstrap/Offcanvas';
import Form from 'react-bootstrap/Form';
import "./Navbar.css";




function Navbar1(){
 return(
      <div>
      <Navbar collapseOnSelect expand="lg" bg="" variant="dark" className=''>
      <Navbar.Brand>
        <font id='heading1'><img src={Logo} className='church-logo'/>Foursquare</font>
       </Navbar.Brand>
        <Container className="d-flex justify-content-end">
         <Navbar.Collapse id="basic-navbar-nav">
        <Nav className='navlink1'>
          <Nav.Link href="#" style={{color:'blue'}} className='mx-5'>HOME</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}} className='mx-5'>ABOUT</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}} className='mx-5'> SERVE</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}}>MEDIA</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}} className='mx-5'>CONTANT US</Nav.Link>
        </Nav>
        </Navbar.Collapse>
         </Container>
      </Navbar>
      
    <Navbar bg="dark" variant="dark" expand="lg">
      <Container>
        <Navbar.Brand href="#">MyApp</Navbar.Brand>

        {/* Toggle button (hamburger) */}
        <Navbar.Toggle aria-controls="basic-navbar-nav" />

        {/* Collapsible content */}
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="ms-auto">
            <Nav.Link href="#">Home</Nav.Link>
            <Nav.Link href="#">About</Nav.Link>
            <Nav.Link href="#">Contact</Nav.Link>
          </Nav>
        </Navbar.Collapse>

      </Container>
    </Navbar>

   </div>

);
}
export default Navbar1;
